package com.lqq.supportflow.knowledge.api;
import com.lqq.supportflow.knowledge.application.RegisterKnowledgeDocumentService; import com.lqq.supportflow.knowledge.domain.KnowledgeDocument; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/knowledge-bases/{knowledgeBaseId}/documents") public class AdminKnowledgeDocumentController { private final RegisterKnowledgeDocumentService service; public AdminKnowledgeDocumentController(RegisterKnowledgeDocumentService service){this.service=service;}
 @PostMapping ResponseEntity<KnowledgeDocument> register(@AuthenticationPrincipal AuthenticatedPrincipal p,@PathVariable Long knowledgeBaseId,@Valid @RequestBody RegisterKnowledgeDocumentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(p.tenantId(),knowledgeBaseId,r.fileName(),r.content()));}}
